import { buildApp } from './app.js';
import { createPool, migrate } from './database.js';
import { PrivateIdService, SignedCredentialProofProvider } from './domain.js';
import { PostgresStateStore } from './state-store.js';
import { BillingService, PostgresBillingStore, StripeGateway, UnavailableBillingGateway } from './billing.js';
import staticPlugin from '@fastify/static';
import { resolve } from 'node:path';
const pool = createPool();
await migrate(pool);
const service = new PrivateIdService(new SignedCredentialProofProvider(process.env.PRIVATEID_PROOF_SECRET ?? '', process.env.PRIVATEID_ISSUER ?? ''), new PostgresStateStore(pool));
await service.hydrate();
const plans = [{ id: 'free', name: 'Free', priceMonthly: 0, currency: 'USD', features: ['Identity wallet'], roleLimits: { proofs: 20 } }, { id: 'professional', name: 'Professional', priceMonthly: 1200, currency: 'USD', stripePriceId: process.env.STRIPE_PRICE_PROFESSIONAL, features: ['Expanded wallet', 'Priority support'], roleLimits: { proofs: 100 } }, { id: 'business', name: 'Business', priceMonthly: 4900, currency: 'USD', stripePriceId: process.env.STRIPE_PRICE_BUSINESS, features: ['Issuer and verifier workspace'], roleLimits: { proofs: 1000 } }];
const gateway = process.env.STRIPE_SECRET_KEY ? new StripeGateway(process.env.STRIPE_SECRET_KEY, process.env.STRIPE_WEBHOOK_SECRET ?? '') : new UnavailableBillingGateway();
const billing = new BillingService(plans, new PostgresBillingStore(pool), gateway, process.env.SITE_URL ?? 'http://localhost:3001');
const app = await buildApp(service, billing);
await app.register(staticPlugin, { root: resolve(process.cwd(), 'web-dist'), prefix: '/site/' });
app.addHook('onClose', async () => pool.end());
await app.listen({ port: Number(process.env.PORT ?? 3001), host: '0.0.0.0' });
